if(view==='mine'&&state)h=title('My submissions.','Your latest 100 submissions and review decisions.')+'<button data-new="market">New submission</button><div class="stack" style="margin-top:20px">'+(state.content.map(c=>'<article class="card"><h2>'+esc(c.title)+'</h2><p>'+esc(names[c.kind])+' · '+esc(c.status)+'</p><p>'+esc(c.notes||'')+'</p>'+(c.status!=='ARCHIVED'?'<button class="quiet" data-withdraw="'+esc(c._id)+'">Withdraw</button>':'')+'</article>').join('')||empty('You have not submitted anything yet.'))+'</div>';
if(view==='inbox'&&state)h=title('My requests.','Check here for new requests and responses. Email alerts point you back here for new messages. For urgent help, call the business directly.')+'<div class="stack">'+(state.requests.map(r=>'<article class="card"><h2>'+esc(r.title)+'</h2><p class="badge">'+esc(r.status)+'</p><p>'+esc(r.incoming?'Received from '+r.senderName:'Sent by you')+'</p><p class="record">'+esc(r.body)+'</p>'+(r.reply?'<blockquote>'+esc(r.reply)+'</blockquote>':'')+(r.incoming?'<button data-response="'+esc(r._id)+'">Respond</button>':'<button class="quiet" data-cancel="'+esc(r._id)+'">Close my request</button>')+'</article>').join('')||empty('No requests yet.'))+'</div>';
if(view==='rules')h=title('A good place to do business.')+'<div class="card"><h2>How this store works</h2><p>Profiles and contributions are reviewed before publication. A credential badge describes the evidence reviewed, with an expiry date; it is not a guarantee of work quality or a universal license.</p><p>Customers use this store free. Lighthouse collects locksmith subscriptions only; customers pay locksmiths directly. Discuss prices, service scope, authorization, appointment timing and any changes directly with the business. Lighthouse inquiries do not dispatch a technician, collect payment or reserve goods. The Key Shop is not open for sales.</p><h2>Community rules</h2><p>Be respectful. Post only material you have the right to share. No scams, stolen goods, private customer details, credentials, access codes or instructions for unauthorized entry. Use Report to flag a concern.</p><h2>Your information</h2><p>Your application notes and inbox are restricted to the account participants and authorized administrators. Approved business contact details and public listings are visible to visitors. Trade discussions and marketplace listings are restricted to approved members. Contact Lighthouse to request correction or deletion of your account data.</p></div>';
